from review import card,save,DATE

def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d

def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

id='TCS-1912';_,c=card(id);refs=c['references'];refs[0]['locator']='APPROX/RANDOM 2025, article 57: Section 1 definitions and capacity formula, Section 1.2 subfield discussion, and second question in Section 1.3 read. The target is erasure list recovery near the small-field capacity, not the large-alphabet Singleton threshold.'
refs.extend([dict(id='random_lower',title='Bounds for List-Decoding and List-Recovery of Random Linear Codes',authors='Venkatesan Guruswami, Ray Li, Jonathan Mosheiff, Nicolas Resch, Shashwat Silas, Mary Wootters',year=2020,url='https://doi.org/10.4230/LIPIcs.APPROX/RANDOM.2020.9',locator='Theorem 6 read: q=ℓ^t, fixed erasure fraction ρ<1 and ε≤(1−ρ)/(20t); random codes at rate (1−ρ)(1−1/t)−ε fail with list bound ℓ^{ceil((1−ρ)/(20ε))}. Its (1−ρ,ℓ,L) notation records the retained fraction; this card uses the 2025 source’s erased-fraction notation.'),dict(id='survey',title='List Recoverable Codes: The Good, the Bad, and the Unknown (hopefully not Ugly)',authors='Nicolas Resch, S. Venkitesh',year=2025,url='https://arxiv.org/abs/2510.07597',locator='Section 4.3, Question 4.5 and the distinction from Theorem 4.7 read in full. The survey repeats the all-linear-code erasure question and distinguishes the large-field result.'),dict(id='all_linear_errors',title='Near-Optimal List-Recovery of Linear Code Families',authors='Ray Li, Nikhil Shagrithaya',year=2025,url='https://doi.org/10.4230/LIPIcs.APPROX/RANDOM.2025.53',locator='Theorem 12 read: for sufficiently large block length, a linear code of rate R that is (1−R−δ,ℓ,L)-list-recoverable from errors satisfies L>ℓ^{floor(R/δ)}. This uses a different gap and does not resolve the fixed-small-field erasure target.')])
save(id,dict(title='Exponential erasure-list sizes for every small-field linear code',formal='Fix a prime power ℓ≥2, an integer t≥2, q=ℓ^t and an erased-coordinate fraction α∈[0,1). Must every F_q-linear code of rate at least (1−α)(1−1/t)−ε that is list-recoverable from α erasures with input lists of size ℓ require output list size L≥ℓ^{c/ε}, for some c>0 and all sufficiently small ε>0 and sufficiently large block lengths? Here c and the small-ε threshold may depend on the fixed ℓ,t,α, but not on ε, the block length or the code.',definitions='A q-ary linear code C is a vector subspace of F_q^n. Its rate is dim_{F_q}(C)/n, where n is the block length. For sets T_1,…,T_n⊆F_q, at least ⌈(1−α)n⌉ sets must have size at most ℓ; the other coordinates may be erased by taking T_i=F_q. The code is (α,ℓ,L)-list-recoverable from erasures when |C∩(T_1×⋯×T_n)|≤L for every such choice of sets. Thus one common set of coordinates is erased and every remaining coordinate must agree with its list. Define L_α,ℓ(C) as the largest such intersection. The erasure-list capacity is R*=(1−α)(1−log_qℓ)=(1−α)(1−1/t), so ε is an additive rate gap below R*. The precise asymptotic question is: for each fixed ℓ,t,α, do constants c,ε_0>0 exist such that for every 0<ε<min{ε_0,R*}, some n_0 makes every n≥n_0 and every F_q-linear C of rate at least R*−ε satisfy L_α,ℓ(C)≥ℓ^{c/ε}? The threshold n_0 may depend on all fixed parameters and ε. This expands the source’s Ω notation in the fixed-field, fixed-erasure regime it studies. The code is arbitrary, with no random choice, explicit-construction promise or efficient-decoding requirement.',question_type='yes_no',answer_criterion='Prove this universal output-list lower bound with constants independent of ε and n, or give code families that refute the stated asymptotic quantifiers. A lower bound that holds only with high probability for random linear codes, or a bound measured from a different capacity threshold, does not suffice.',context_blocks=[b('The input and output lists describe different uncertainties','Each small T_i gives possible symbols at one unerased coordinate. The output list consists of entire codewords compatible with all those coordinate restrictions. Even when every T_i is tiny, many complete codewords can survive.'),b('A concrete small-field example','For q=4, ℓ=2 and no erased coordinates, the capacity rate is 1/2. The question asks whether every quaternary linear code with rate near 1/2 needs an output list exponential in the inverse rate gap, for some choice of two-symbol coordinate lists.'),b('Random linear codes already face this obstruction','The Guruswami–Li–Mosheiff–Resch–Silas–Wootters theorem gives the exponential lower bound with high probability for random linear codes over fields containing F_ℓ. The open question is whether specially chosen linear codes can avoid it. Unrestricted random codes can have output lists only O(ℓ/ε).', 'random_lower'),b('The known all-linear-code theorem measures a different gap','Li–Shagrithaya prove an exponential lower bound for error list recovery at radius 1−R−δ. Substituting the erasure capacity rate here gives δ=(1−α)/t+ε when the error radius is α. For fixed t this δ does not tend to zero with ε, so that theorem does not supply the required ℓ^{Ω(1/ε)} conclusion.', 'all_linear_errors'),b('Prime fields are a different regime','The 2025 source obtains O(1/ε) output-list bounds for erasure list recovery of random linear codes over fixed prime fields. The present question instead assumes q=ℓ^t with t≥2, so it cannot be refuted merely by citing those prime-field results.', 'primary')],why='Would determine whether the exponential price in output-list size is intrinsic to linearity over small extension fields, or merely a limitation of random linear code ensembles.',progress=[dict(date='2020',text='The exponential erasure-list lower bound is proved for random linear codes over q=ℓ^t.',citation='random_lower'),dict(date='2025',text='The small-field paper and the later survey ask whether the obstruction applies to every linear code.',citation='survey'),dict(date='2025',text='A universal linear-code lower bound is proved near the error-list Singleton threshold; it does not answer the fixed-small-field erasure question.',citation='all_linear_errors')],references=refs,status='source_open',status_note='Original definitions and random-code theorem, the later survey, Li–Shagrithaya Theorem 12, July 2026 arXiv:2607.19576 and September 2026 arXiv:2609.06570 checked through 12 September 2026. The newer works concern a different additive-code threshold or random-code list decoding; no resolution of this universal erasure-list target was located.',model_self_contained=True,requires_context=False,importance=imp(c,'Tests whether a sharp separation between linear and nonlinear list-recoverable codes is intrinsic at small field size.'),review_note='Recovered the missing bound, field structure, erased-coordinate convention and capacity gap. Made the fixed-parameter Ω quantifiers explicit and checked that the recent all-linear/additive results concern a different threshold.',working_summary=sm(['An erasure-list recovery instance provides a few possible symbols at each retained coordinate.','At rate ε below capacity over q=ℓ^t, random linear codes can have exponentially many compatible codewords in 1/ε.','The question is whether every linear code over these fixed extension fields must suffer that cost.','The relevant capacity is (1−α)(1−1/t), where α is the erased fraction.','Known all-linear-code results near the large-alphabet error threshold do not establish the same lower bound here.'],['primary','random_lower','survey','all_linear_errors'])),notes=['Restored the exponential list bound and fixed-small-field erasure capacity.','Defined retained lists, code rate and every-code asymptotic quantifiers.','Distinguished the random-code theorem and newer error-list/additive barriers from the target.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2607.19576','https://arxiv.org/abs/2609.06570','https://arxiv.org/abs/2505.05935'])

id='TCS-1965';_,c=card(id);refs=c['references'];refs[0]['locator']='OPODIS 2024, article 26: Section 1.1 model, local/global discussion and Section 5 conclusion on p. 26:14 read. The open target is simultaneous Õ(t) rounds and Õ(n) messages for all t≤D; the paper settles t=D.'
refs.append(dict(id='preprint',title='The Singular Optimality of Distributed Computation in LOCAL — version record',authors='Fabien Dufoulon, Gopal Pandurangan, Peter Robinson, Michele Scquizzato',year=2024,url='https://arxiv.org/abs/2411.07011',locator='Submitted 11 November 2024. Full abstract and the accepted-version repository record checked; its global result is not an all-t theorem.'))
issue='The source’s universal “any problem/algorithm” question does not select the deterministic versus randomized simulation requirement or state the success and resource guarantees for the randomized version. A complete benchmark must also fix the initially available global bounds (such as n or t), the problem’s local input/output conventions, and whether it asks only for an equally good solver or an exact simulation. The quantitative resource target and KT1 model are recovered without silently adding those choices.'
save(id,dict(title='Nearly linear messages without slowing local distributed computation',formal='If a distributed problem admits an O(t)-round LOCAL algorithm, with 1≤t≤D, must it admit a KT1 LOCAL algorithm using both Õ(t) rounds and Õ(n) total messages on n-vertex networks of diameter D? The source leaves the universal simulation’s randomness and success conventions implicit; those choices remain to be fixed for a single benchmark.',definitions='The network is a finite connected undirected graph G=(V,E), with n=|V| and hop diameter D=max_{u,v}dist_G(u,v). Processors at the vertices communicate synchronously along graph edges. In one round each processor receives previous messages, performs unrestricted local computation, and can send a message to each neighbor. LOCAL places no bound on message length. Round complexity measures time until the processors finish and produce their required outputs; message complexity counts all directed transmissions across all rounds and vertices, not the total number of transmitted bits. Under KT1, a processor initially knows its own identifier and the identifiers of its neighbors, with the corresponding communication ports; KT0 does not provide neighboring identifiers. For fixed problem and algorithm, the requested simultaneous bounds mean at most C t(log(n+2))^a rounds and C n(log(n+2))^b messages for constants C,a,b independent of n,t,D and the particular input. In a randomized version it must additionally be specified whether correctness, round counts and message counts hold surely, in expectation or with a stated high probability. The new solver must solve the same distributed input/output relation; the source does not require that it reproduce the original algorithm’s exact execution.',question_type='yes_no',answer_criterion='Fix the universal problem, information and randomness conventions, then prove the simultaneous Õ(t)-round/Õ(n)-message guarantee for every admissible problem and t≤D, or give an obstruction within those same conventions. Separate algorithms attaining the two bounds, a global Õ(D)-round algorithm, or an Õ(nt)-message simulation do not establish the claimed simultaneous guarantee.',context_blocks=[b('A quick local algorithm can still send many messages','In one LOCAL round every edge may carry a transmission in each direction. A dense network can therefore spend Θ(n²) messages in one round. KT1 supplies neighboring identifiers without requiring those transmissions, which can matter greatly when messages are the scarce resource.'),b('The global scale is already settled','The paper gives a deterministic KT1 LOCAL algorithm using Õ(D) rounds and Õ(n) messages for global computation, including breadth-first search. When t is much smaller than D, waiting for that global computation can exceed the desired Õ(t) time.', 'primary'),b('Known simulation bounds still depend on t','The source recalls message-reduction schemes with roughly O(t log n+log²n) rounds and O(nt log n+n log²n) messages. For polylogarithmic t this is already nearly linear in messages; a polynomially growing t leaves a substantial gap.', 'primary'),b('Message length changes the question','One LOCAL message may contain a large accumulated data structure. CONGEST instead limits bits sent per edge per round. The source separately asks about global singular optimality in CONGEST; that unresolved task is not the one selected here.', 'primary')],why='Asks whether distributed computation has a general tradeoff between locality and communication volume, or whether almost all unnecessary messages can be removed while preserving each problem’s own round scale.',progress=[dict(date='2024',text='The OPODIS paper establishes simultaneous Õ(D) rounds and Õ(n) messages for global KT1 LOCAL computation and asks for the all-t extension.',citation='primary')],references=refs,status='uncertain',status_note='Source model, known simulations, global theorem and subsequent searches checked through 12 September 2026. No all-t resolution was located. The universal randomized/deterministic and information conventions remain to be specified.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',notes=['Recovered the simultaneous bounds and initial-knowledge model; left the universal simulation conventions explicit.'],remaining_issue=issue),importance=imp(c,'A general communication-versus-locality question in distributed computing.'),review_note='Recovered the truncated all-t statement and distinguished messages from bits and t from network diameter. Did not silently impose deterministic simulation or a high-probability convention on the source’s unqualified universal question.',working_summary=sm(['A LOCAL algorithm may finish in t rounds while sending messages across many network edges.','The question asks whether the same task can always be solved in nearly t rounds with only nearly n total messages.','KT1 gives processors their neighbors’ identifiers at the start, and LOCAL permits unbounded message length.','The paper already achieves the desired message bound at the global diameter scale.','The all-t extension still needs precise randomness, success and initial-information conventions.'],['primary','preprint'])),state='improved_unfinished',notes=['Restored the simultaneous Õ(t)-round and Õ(n)-message target for t≤D.','Defined LOCAL, KT1, diameter and directed message counting.','Separated known global and Õ(nt)-message results and recorded the unresolved universal-model conventions.'],checked_sources=[r['url'] for r in refs]+['https://eprints.lancs.ac.uk/id/eprint/226214/'])
